  out.note = Object.assign({
    body: `Complaint after the review request: ${out.issue}\nThey wrote (${ctx.channel}): "${ctx.text.slice(0, 500)}"\n${apology}: "${reply}"\n`
      + `Recovery task due ${out.dueLabel}. The review request itself was not changed.`,
  }, ownerId ? { userId: ownerId } : {});
}
