const P = String($env.TAG_PREFIX || 'review').trim().toLowerCase();
// Tags the GoHighLevel workflows add (the n8n side only reads these, it never writes or removes them)
// and tags the n8n side adds.
const TAG = {
  requested: `${P}-requested`, reminded: `${P}-reminded`, replied: `${P}-replied`, clicked: `${P}-link-clicked`,
  praise: `${P}-reply-praise`, complaint: `${P}-reply-complaint`, question: `${P}-reply-question`, other: `${P}-reply-other`,
  recovery: `${P}-needs-recovery`, human: `${P}-needs-human`, stopped: `${P}-opted-out`,
};

const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// n8n error items carry message, or (for paginated requests) only statusCode and the response body in error.
const err = e => String(!e ? 'unknown error' : typeof e === 'string' ? e : (e.message || e.description
  || (e.statusCode ? `${e.statusCode} - ${typeof e.error === 'string' ? e.error : JSON.stringify(e.error || '')}` : JSON.stringify(e)))).slice(0, 300);
// The result of an HTTP node: its normal output, or the item on its error output (which carries json.error).
const result = name => {
  if (!$(name).isExecuted) return null;
  const ok = $(name).all(0);
  if (ok.length) return ok[0].json;
  const bad = $(name).all(1);
  return bad.length ? bad[0].json : null;
};

// Every branch ends here. Decides the message back, the tags, the alert and whether the run is marked as failed,
// and keeps the reply log the weekly digest reads.
const ctx = $('Build Reply Context').first().json;
const decision = $('Read Decision').isExecuted ? $('Read Decision').first().json : null;
const route = decision ? decision.route : ctx.action;
const store = $getWorkflowStaticData('global');
store.leads = store.leads || {};
store.replyLog = store.replyLog || [];
const lead = store.leads[ctx.contactId] = Object.assign({ replies: 0 }, store.leads[ctx.contactId] || {});
const now = new Date().toISOString();
const first = ctx.firstName || 'there';
const business = String($env.BUSINESS_NAME || 'our team').trim();
const who = slackSafe(`${ctx.name} (${ctx.phone || ctx.email || 'no phone'})`);
const link = `${String($env.GHL_APP_URL || 'https://app.gohighlevel.com').replace(/\/+$/, '')}/v2/location/${$env.GHL_LOCATION_ID}/contacts/detail/${ctx.contactId}`;
const HOLD = `Thanks for your message, ${first}. Someone from ${business} will get back to you shortly.`;
const said = `They wrote (${ctx.channel}): "${slackSafe(ctx.text.slice(0, 500))}"`;
const o = { message: '', tags: [], alert: '', fail: '', logType: 'other' };
const fails = [];
// The quiet hours decision made after Claude answered, or before any AI for the other routes.
const sendAt = decision ? decision.sendAt : ctx.sendAt;
const sendLabel = decision ? decision.sendLabel : ctx.sendLabel;
const sentLine = text => sendAt ? `They will get this at ${sendLabel} their time (quiet hours): "${slackSafe(text)}"` : `They got: "${slackSafe(text)}"`;

// An earlier reply that was waiting for the morning: cancelled, or still scheduled if GoHighLevel refused.
const cancel = result('GHL: Cancel Scheduled Reply');
if (cancel && !cancel.error) { lead.replies = Math.max((lead.replies || 1) - 1, 0); lead.pending = null; }
const cancelFailed = cancel && cancel.error ? err(cancel.error) : '';
// A message that may ask us to stop goes to a person, who decides about DND.
const stopNote = (ctx.stopHint ? '\nTheir message may ask us to stop. Set DND by hand if it does.' : '')
  + (cancel && !cancel.error ? `\nThe reply that was waiting for ${ctx.pendingLabel} was cancelled.` : '');

if (route === 'opt_out') {
  o.tags.push(TAG.stopped);
  o.logType = 'opt_out';
  lead.optedOutAt = now;
  if (cancelFailed) fails.push(`URGENT: ${who} asked to stop messages. DND is on for ${ctx.dndLabel}, but the reply scheduled for ${ctx.pendingLabel} could not be cancelled (${cancelFailed}). Delete it in their conversation now.`);
} else if (route === 'reply') {
  o.message = decision.reply;
  o.tags.push(TAG.praise);
  o.logType = 'praise';
} else if (route === 'recovery') {
  o.message = decision.reply;
  o.tags.push(TAG.complaint, TAG.recovery);
  o.logType = 'complaint';
  const task = result('GHL: Create Recovery Task');
  const noteRes = result('GHL: Add Recovery Note');
  const taskLine = task && !task.error ? `Task for the owner, due ${decision.dueLabel}.` : `The recovery task could NOT be created (${slackSafe(err(task && task.error))}). Add it by hand.`;
  o.alert = `*Service recovery needed*: ${who}\nIssue: ${slackSafe(decision.issue)}\n${said}\n${taskLine}\n${sentLine(o.message)}\n`
    + `Their review request was not changed. Do not offer anything in exchange for changing or removing a review.\n${link}`;
  if (!task || task.error) fails.push(`The service recovery task for ${who} was not created: ${slackSafe(err(task && task.error))}. Issue: ${slackSafe(decision.issue)}. Add the task by hand.`);
  if (!noteRes || noteRes.error) fails.push(`The complaint note for ${who} was not saved: ${slackSafe(err(noteRes && noteRes.error))}.`);
} else if (route === 'hand_off' && decision) {
  // Question or other: a short holding reply, and a person takes over.
  o.message = HOLD;
  o.tags.push(decision.category === 'question' ? TAG.question : TAG.other, TAG.human);
  o.logType = decision.category;
  o.alert = `*${decision.category === 'question' ? 'Customer question' : 'Customer reply needs a person'}*: ${who}\n${said}\n`
    + `${decision.summary ? slackSafe(decision.summary) + '\n' : ''}${sentLine(o.message)}\n${link}`;
} else if (route === 'hand_off') {
  o.tags.push(TAG.human);
  o.alert = `*Customer reply needs a person*: ${who}\n${said}\nThe assistant stopped replying because ${ctx.reason}.${stopNote}\n${link}`;
} else if (route === 'follow_up') {
  lead.followUpAlertAt = now;
  o.alert = `*New message from a customer a person already has*: ${who}\n${said}\nNo automatic reply was sent.${stopNote}\n${link}`;
} else if (route === 'fallback') {
  // A message with an opt out word in it gets no holding reply: it may be an opt out, and a person decides.
  o.message = ctx.stopHint ? '' : HOLD;
  o.tags.push(TAG.human);
  const held = ctx.stopHint ? 'Nothing was sent, because the message may ask us to stop. Set DND by hand if it does.' : sentLine(HOLD);
  o.alert = `*Customer reply needs a person*: ${who}\n${said}\nClaude could not classify it. ${held}\n${link}`;
  fails.push(`Claude did not give a usable answer for ${who}. ${held} They have the ${TAG.human} tag. ${said}. ${decision.failure}. Check ANTHROPIC_API_KEY, your credit balance and ANTHROPIC_MODEL.`);
}
if (cancelFailed && route !== 'opt_out')
  fails.push(`An earlier reply to ${who} is still scheduled for ${ctx.pendingLabel} and could not be cancelled (${cancelFailed}), so they may get two messages.`);
if (ctx.historyProblem)
  fails.push(`Handled the reply from ${who} without the conversation history, because GoHighLevel did not return it (${slackSafe(ctx.historyProblem)}). Check the conversations.readonly and conversations/message.readonly scopes of GHL_API_KEY.`);
o.fail = fails.join(' ');

// The request to send. SMS outside quiet hours goes now; inside quiet hours GoHighLevel holds it until the morning.
let sendBody = null;
if (o.message) {
  if (ctx.channel === 'Email') {
    const html = o.message.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    sendBody = { type: 'Email', contactId: ctx.contactId, subject: `${business}: thanks for your reply`, html: `<p>${html}</p>` };
  } else {
    sendBody = Object.assign({ type: 'SMS', contactId: ctx.contactId, message: o.message }, $env.GHL_FROM_NUMBER ? { fromNumber: String($env.GHL_FROM_NUMBER) } : {});
    if (sendAt) sendBody.scheduledTimestamp = Math.floor(new Date(sendAt).getTime() / 1000);
  }
}
store.replyLog.push({ at: now, type: o.logType, contactId: ctx.contactId, name: ctx.name, issue: decision && decision.route === 'recovery' ? decision.issue : '' });
store.replyLog = store.replyLog.filter(e => Date.now() - new Date(e.at).getTime() < 60 * 86400000).slice(-2000);
Object.assign(lead, { lastType: o.logType, updatedAt: now });
for (const [id, l] of Object.entries(store.leads)) if (Date.now() - new Date(l.updatedAt || 0).getTime() > 90 * 86400000) delete store.leads[id];
return [{ json: Object.assign(o, { contactId: ctx.contactId, name: ctx.name, channel: ctx.channel, route, sendBody, sendAt, sendLabel }) }];

const slackSafe = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
