  || (e.statusCode ? `${e.statusCode} - ${typeof e.error === 'string' ? e.error : JSON.stringify(e.error || '')}` : JSON.stringify(e)))).slice(0, 300);
// The result of an HTTP node: its normal output, or the item on its error output (which carries json.error).
const result = name => {
  if (!$(name).isExecuted) return null;
  const ok = $(name).all(0);
  if (ok.length) return ok[0].json;
  const bad = $(name).all(1);
  return bad.length ? bad[0].json : null;
};

// Records the send and puts the alert together. A failure ends the run as failed, so the error workflow alerts you.
const o = $('Outcome').first().json;
const store = $getWorkflowStaticData('global');
store.leads = store.leads || {};
const lead = store.leads[o.contactId] = store.leads[o.contactId] || { replies: 0 };
const sent = result('GHL: Send Reply');
const tagResult = result('GHL: Add Tags');
const ok = Boolean(sent && !sent.error);
if (ok) {
  lead.replies = (lead.replies || 0) + 1;
  lead.pending = o.sendBody && o.sendBody.scheduledTimestamp ? { messageId: sent.messageId || '', sendAt: o.sendAt, label: o.sendLabel } : null;
}
const problems = [o.fail];
if (sent && sent.error) problems.push(`The ${o.channel === 'Email' ? 'email' : 'SMS'} reply to ${slackSafe(o.name)} was NOT sent: ${slackSafe(err(sent.error))}. Send it by hand: "${slackSafe(o.message)}"`);
if (tagResult && tagResult.error) problems.push(`Tags ${o.tags.join(', ')} were not saved on ${slackSafe(o.name)}: ${slackSafe(err(tagResult.error))}`);
const fail = problems.filter(Boolean).join(' ');
return [{ json: { contactId: o.contactId, route: o.route, sent: ok, scheduled: ok && Boolean(o.sendBody && o.sendBody.scheduledTimestamp),
  messageId: ok ? sent.messageId || '' : '', alert: o.alert, fail, postToSlack: Boolean($env.SLACK_WEBHOOK_URL && o.alert) } }];

const P = String($env.TAG_PREFIX || 'review').trim().toLowerCase();
// Tags the GoHighLevel workflows add (the n8n side only reads these, it never writes or removes them)
// and tags the n8n side adds.
const TAG = {
  requested: `${P}-requested`, reminded: `${P}-reminded`, replied: `${P}-replied`, clicked: `${P}-link-clicked`,
