  recovery: `${P}-needs-recovery`, human: `${P}-needs-human`, stopped: `${P}-opted-out`,
};

// Checks the settings every part of the workflow needs. Problems are listed, not thrown, so the run can stop with the whole list.
function settingsProblems(extra) {
  const problems = [];
  const need = (name, value, why) => { if (!String(value ?? '').trim()) problems.push(`${name} is empty${why ? ', so ' + why : ''}`); };
  need('GHL_API_KEY', $env.GHL_API_KEY);
  need('GHL_LOCATION_ID', $env.GHL_LOCATION_ID);
  need('GHL_FIELD_REQUEST_SENT_ID', $env.GHL_FIELD_REQUEST_SENT_ID, 'review requests cannot be recorded or counted');
  need('GHL_FIELD_REMINDER_SENT_ID', $env.GHL_FIELD_REMINDER_SENT_ID, 'reminders cannot be recorded or counted');
  const tz = String($env.BUSINESS_TZ || 'America/New_York').trim();
  if (!DateTime.now().setZone(tz).isValid) problems.push(`BUSINESS_TZ "${tz}" is not a valid time zone`);
  const hour = (v, d) => { const s = String(v ?? '').trim(); if (!s) return d; const n = Number(s); return Number.isInteger(n) && n >= 0 && n <= 24 ? n : null; };
  const start = hour($env.SEND_HOUR_START, 8), end = hour($env.SEND_HOUR_END, 20);
  if (start === null || end === null || start >= end) problems.push('SEND_HOUR_START and SEND_HOUR_END must be whole hours from 0 to 24, with the start before the end');
  for (const p of extra || []) if (p) problems.push(p);
  return { problems, tz, start, end };
}

// The digest covers the last 7 days. Requests and reminders are counted from the times the workflow saved on the
// contacts, so only contacts with the request tag that changed in that week are searched.
const s = settingsProblems([String($env.SLACK_WEBHOOK_URL || '').trim() ? '' : 'SLACK_WEBHOOK_URL is empty, so the digest has nowhere to go (set DIGEST_ENABLED=false to turn the digest off)']);
const until = new Date();
const since = new Date(until.getTime() - 7 * 86400000);
const pageSize = Math.min(Math.max(Math.floor(Number($env.SEARCH_PAGE_SIZE) || 100), 1), 500);
const maxPages = Math.min(Math.max(Math.floor(Number($env.MAX_SEARCH_PAGES) || 10), 1), 50);
const locationId = String($env.GHL_LOCATION_ID || '');
return [{ json: {
  trigger: $('Run Digest').isExecuted ? 'run now' : 'schedule',
  ok: s.problems.length === 0,
  fail: s.problems.length ? `The weekly review digest was not posted, because the settings are not valid. ${s.problems.join('. ')}.` : '',
  since: since.toISOString(), until: until.toISOString(), tz: s.tz, pageSize, maxPages,
  requestedSearch: { locationId, pageLimit: pageSize, filters: [
    { field: 'tags', operator: 'eq', value: TAG.requested },
    { field: 'dateUpdated', operator: 'range', value: { gt: since.toISOString() } },
  ], sort: [{ field: 'dateUpdated', direction: 'desc' }] },
  recoverySearch: { locationId, pageLimit: pageSize, filters: [{ field: 'tags', operator: 'eq', value: TAG.recovery }],
    sort: [{ field: 'dateUpdated', direction: 'desc' }] },
} }];

// One item per contact with the needs-recovery tag, so their tasks can be loaded. None: a single empty item.
const pages = $('GHL: Search Recovery').all(0).map(i => i.json);
const seen = new Set();
const out = [];
for (const p of pages) for (const c of p.contacts || []) {
  if (!c || !c.id || seen.has(c.id)) continue;
  seen.add(c.id);
  const name = [c.firstNameLowerCase, c.lastNameLowerCase].filter(Boolean).map(s => s.charAt(0).toUpperCase() + s.slice(1)).join(' ') || c.email || c.phone || c.id;
  out.push({ json: { contactId: c.id, name } });
}
return out.length ? out : [{ json: { contactId: '' } }];

