const err = e => String(!e ? 'unknown error' : typeof e === 'string' ? e : (e.message || e.description
  || (e.statusCode ? `${e.statusCode} - ${typeof e.error === 'string' ? e.error : JSON.stringify(e.error || '')}` : JSON.stringify(e)))).slice(0, 300);
// The result of an HTTP node: its normal output, or the item on its error output (which carries json.error).
const result = name => {
  if (!$(name).isExecuted) return null;
  const ok = $(name).all(0);
  if (ok.length) return ok[0].json;
