// Puts the weekly digest together. Any GoHighLevel failure means the numbers would be wrong, so nothing is posted and
// the run fails with the reason.
const s = $('Digest Settings').first().json;
const since = new Date(s.since).getTime(), until = new Date(s.until).getTime();
const fmt = (iso, withTime) => DateTime.fromISO(iso).setZone(s.tz).toFormat(withTime ? 'ccc, LLL d, h:mm a' : 'LLL d');
const problems = [];
const failed = (name, what) => { const bad = $(name).isExecuted ? $(name).all(1) : []; if (bad.length) problems.push(`${what}: ${err(bad[0].json.error)}`); };
failed('GHL: Search Requested', 'the contact search for review requests failed');
failed('GHL: Search Recovery', 'the contact search for open recovery work failed');

const inWindow = v => { const t = new Date(String(v || '')).getTime(); return Number.isFinite(t) && t > since && t <= until; };
const contacts = new Map();
for (const page of $('GHL: Search Requested').all(0)) for (const c of page.json.contacts || []) if (c && c.id) contacts.set(c.id, c);
const fieldValue = (c, id) => ((c.customFields || []).find(f => f && f.id === id) || {}).value;
let requests = 0, reminders = 0;
for (const c of contacts.values()) {
  if (inWindow(fieldValue(c, String($env.GHL_FIELD_REQUEST_SENT_ID || '')))) requests++;
  if (inWindow(fieldValue(c, String($env.GHL_FIELD_REMINDER_SENT_ID || '')))) reminders++;
}
const log = ($getWorkflowStaticData('global').replyLog || []).filter(e => inWindow(e.at));
const count = t => log.filter(e => e.type === t).length;
const parts = [['praise', 'praise'], ['complaint', 'complaint'], ['question', 'question'], ['opt_out', 'opt out'], ['other', 'other']]
  .map(([t, word]) => [count(t), word]).filter(([n]) => n > 0)
  .map(([n, word]) => `${n} ${word}${n > 1 && ['complaint', 'question'].includes(word) ? 's' : ''}`);
const complaints = log.filter(e => e.type === 'complaint');

const names = new Map($('Recovery Contacts').all().map(i => [i.json.contactId, i.json.name]));
const open = [];
const taskItems = $('GHL: Get Tasks').isExecuted ? $('GHL: Get Tasks').all() : [];
const taskErrors = taskItems.filter(i => i.json.error);
if (taskErrors.length) problems.push(`loading the tasks of ${taskErrors.length} contact(s) with the needs-recovery tag failed: ${err(taskErrors[0].json.error)}`);
for (const item of taskItems) for (const t of item.json.tasks || []) {
  if (!t || t.completed || !String(t.title || '').startsWith('Service recovery')) continue;
  open.push({ name: names.get(t.contactId) || t.contactId, due: t.dueDate, overdue: new Date(t.dueDate).getTime() < until });
}
open.sort((a, b) => new Date(a.due).getTime() - new Date(b.due).getTime());

const business = String($env.BUSINESS_NAME || '').trim();
const lines = [
  `*Weekly review report*${business ? ': ' + slackSafe(business) : ''} (${fmt(s.since)} to ${fmt(s.until)})`,
  `Review requests sent: ${requests}`,
  `Reminders sent: ${reminders}`,
  `Replies: ${log.length}${parts.length ? ' (' + parts.join(', ') + ')' : ''}`,
];
if (complaints.length) lines.push('Complaints:', ...complaints.map(e => `• ${slackSafe(e.name)}: ${slackSafe(e.issue)}`));
lines.push(`Open recovery tasks: ${open.length}`, ...open.map(t => `• ${slackSafe(t.name)}, due ${fmt(t.due, true)}${t.overdue ? ' (overdue)' : ''}`));
if (contacts.size >= s.pageSize * s.maxPages) lines.push(`Note: the search stopped at ${contacts.size} contacts, so the request counts may be low. Raise MAX_SEARCH_PAGES.`);
return [{ json: {
  text: lines.join('\n'), requests, reminders, replies: log.length, openTasks: open.length,
  fail: problems.length ? `The weekly review digest was not posted, because ${problems.join('; ')}.` : '',
} }];
